import json,re,decimal
with open('envelope.json') as f: e=json.load(f)
levels={'trim-the-fat':(.90,.95),'less-wordy':(.70,.70),'more-concise':(.60,.60),'more-succinct':(.40,.50),'shorten-markdown-changes-quotes':(.70,.70)}
def words(s):
 return [w for w in s.split() if not re.fullmatch(r'(?:`{3,}(?:[A-Za-z0-9_-]+)?|~{3,}(?:[A-Za-z0-9_-]+)?|[*_~#|>+-]+)',w)]
def rounded(n): return int(decimal.Decimal(str(n)).quantize(decimal.Decimal('1'),rounding=decimal.ROUND_HALF_UP))
for c in e['cases']:
 if c['id'] not in levels: continue
 p=c['prompt'][len(e['runner_context'].rstrip()):].lstrip('\n')
 s=p.split('Source:\n',1)[1] if 'Source:\n' in p else p.split(': ',1)[1]
 n=len(words(s)); lo,hi=levels[c['id']]
 print(json.dumps({'id':c['id'],'source':s,'original_words':n,'budget_min':rounded(n*lo),'budget_max':rounded(n*hi)},ensure_ascii=False))

